import { getMorbisGlobals } from './shared/types.js';

const g = getMorbisGlobals();

interface CpptFilterState {
  search: string;
  dokter: string;
  tanggalAwal: string;
  tanggalAkhir: string;
}

const CPPT_STYLE_ID = 'ext-cppt-search-style';
const CPPT_CONTAINER_ID = 'ext-cppt-filter-container';
const CPPT_NO_RESULTS_ID = 'ext-cppt-no-results';

type CpptPageType = 'rajal' | 'ranap' | null;

function getCpptPageType(): CpptPageType {
  const path = window.location.pathname;
  if (path.includes('/admisi/pelaksanaan_pelayanan/cppt')) return 'rajal';
  if (path.includes('/admisi/detail-rawat-inap/cppt')) return 'ranap';
  return null;
}

function findCpptTable(): HTMLTableElement | null {
  const byId = document.getElementById('history_cppt') as HTMLTableElement | null;
  if (byId) return byId;

  for (const t of document.querySelectorAll<HTMLTableElement>('table')) {
    const firstRow = t.querySelector('tr');
    if (!firstRow) continue;
    const texts = Array.from(firstRow.querySelectorAll('th, td')).map(c =>
      c.textContent?.trim().toLowerCase() || ''
    );
    const keywords = ['waktu', 'penginput', 'subyektif', 'obyektif', 'assessment', 'instruksi'];
    const matchCount = keywords.filter(k => texts.some(t => t.includes(k))).length;
    if (matchCount >= 2) return t;
  }

  for (const t of document.querySelectorAll<HTMLTableElement>('table')) {
    if (t.textContent?.toLowerCase().includes('cppt')) return t;
  }

  return null;
}

function getHeaderTexts(table: HTMLTableElement): string[] {
  const headerRow = table.querySelector('thead tr') || table.querySelector('tr');
  if (!headerRow) return [];
  return Array.from(headerRow.querySelectorAll('th, td')).map(h =>
    h.textContent?.trim() || ''
  ).filter(t => t.length > 0);
}

function getColumnIndex(headers: string[], ...keywords: string[]): number {
  for (const kw of keywords) {
    const idx = headers.findIndex(h => h.toLowerCase().includes(kw));
    if (idx !== -1) return idx;
  }
  return -1;
}

